import type { AwardsSummary, FestivalPrize } from "@/lib/awards";

/**
 * The on-disk shape of awards.generated.json, written by `npm run awards:refresh` and read by
 * awards.ts. Compact on purpose (one line, short keys): there is one entry per film that has an
 * Oscar record or a festival top prize.
 */
export interface AwardsFile {
  /**
   * ISO timestamp of the refresh. The film selection comes from TMDB, whose terms limit how long
   * data derived from it may be kept (six months), so the file has to be regenerated by then.
   */
  generatedAt: string;
  /** Keyed by TMDB movie id. */
  films: Record<string, AwardsFileFilm>;
}

export interface AwardsFileFilm {
  /** Oscar wins. */
  w: number;
  /** Oscar nominations (wins included, as the Academy counts them). */
  n: number;
  /** Festival top prizes won: [festival, prize], e.g. ["Cannes", "Palme d'Or"]. */
  f: [festival: string, prize: string][];
}

/** The films of a refresh, by TMDB id. */
export type FilmAwardsById = ReadonlyMap<number, AwardsSummary>;

export function encodeAwards(films: FilmAwardsById, generatedAt: string): AwardsFile {
  const out: AwardsFile["films"] = {};
  for (const id of [...films.keys()].sort((a, b) => a - b)) {
    const { oscarWins, oscarNominations, festivalPrizes } = films.get(id)!;
    out[String(id)] = {
      w: oscarWins,
      n: oscarNominations,
      f: festivalPrizes.map(({ festival, prize }) => [festival, prize]),
    };
  }
  return { generatedAt, films: out };
}

const isCount = (value: unknown): value is number =>
  typeof value === "number" && Number.isInteger(value) && value >= 0;

function decodePrizes(value: unknown): FestivalPrize[] {
  if (!Array.isArray(value)) return [];
  const prizes: FestivalPrize[] = [];
  for (const entry of value) {
    if (Array.isArray(entry) && typeof entry[0] === "string" && typeof entry[1] === "string") {
      prizes.push({ festival: entry[0], prize: entry[1] });
    }
  }
  return prizes;
}

/**
 * The lookup for a (possibly empty or damaged) file. An entry that is not shaped as expected, or
 * that says nothing (no Oscar record, no prize), is left out, so the caller shows no row for it.
 */
export function decodeAwards(file: unknown): Map<number, AwardsSummary> {
  const lookup = new Map<number, AwardsSummary>();
  const films = (file as Partial<AwardsFile> | null | undefined)?.films;
  if (!films || typeof films !== "object") return lookup;

  for (const [key, entry] of Object.entries(films)) {
    const id = Number(key);
    if (!Number.isInteger(id) || id <= 0 || !entry || typeof entry !== "object") continue;
    const { w, n, f } = entry as Partial<AwardsFileFilm>;
    // A win is also a nomination; an entry that says otherwise is damaged, so it is left out.
    if (!isCount(w) || !isCount(n) || w > n) continue;
    const festivalPrizes = decodePrizes(f);
    if (n === 0 && festivalPrizes.length === 0) continue;
    lookup.set(id, { oscarWins: w, oscarNominations: n, festivalPrizes });
  }
  return lookup;
}
